CREATE TABLE Caches (Code text default '' not null, Name text default '' not null, PlacedBy text default '' not null, Archived integer default 0 not null, CacheType text default 'O' not null, Container text default 'Unknown' not null, County text default '' not null, Country text default '' not null, Difficulty real default 1.0 not null, FoundByMeDate text default '' not null, Latitude text default '0.0' not null, Longitude text default '0.0' not null, OwnerId text default '' not null, OwnerName text default '' not null, PlacedDate text default current_date not null, State text default '' not null, TempDisabled integer default 0 not null, Terrain real default 1.0 not null, LatOriginal text default '0.0' not null, LonOriginal text default '0.0' not null, Elevation real default 0.0 not null, FavPoints Integer default 0 not null);
CREATE TABLE CacheMemo (Code text default '' not null, ShortDescription text default '' not null, Hints text default '' not null);
CREATE TABLE Waypoints (cParent not null, cCode not null, cPrefix, cName, cType, cLat, cLon, cByuser boolean, cDate date, cFlag boolean, sB1 boolean);
CREATE TABLE Custom (cCode text default '' not null primary key);
